export const PairedEffectEstimateSchema = z.object({
  "schema_version": z.literal("ecocorridor-usefulness-study/v1.0").optional(),
  "effect_id": z.string().min(1).max(160),
  "outcome_id": z.string().min(1).max(128),
  "reference_arm_id": z.string().min(1).max(96),
  "comparison_arm_id": z.string().min(1).max(96),
  "estimand": z.string().min(1).max(200),
  "unit": z.string().min(1).max(64),
  "direction": z.enum(["LOWER_IS_BETTER", "HIGHER_IS_BETTER"]),
  "pair_count": z.number().int().min(2),
  "estimate": z.number(),
  "confidence_level": z.number().gt(0.5).lt(1).optional(),
  "confidence_interval_low": z.number(),
  "confidence_interval_high": z.number(),
  "bootstrap_seed": z.number().int(),
  "bootstrap_resamples": z.number().int().min(100),
  "noninferiority_margin": z.union([z.number().min(0), z.null()]).optional(),
  "conclusion": z.enum(["IMPROVED", "NONINFERIOR", "WORSE", "INCONCLUSIVE"]),
}).strict();
export type PairedEffectEstimate = z.infer<typeof PairedEffectEstimateSchema>;

export const ShadowProjectRecordSchema = z.object({
  "schema_version": z.literal("ecocorridor-usefulness-study/v1.0").optional(),
  "shadow_record_id": z.string().min(1).max(128),
  "partner_pseudonym_sha256": z.string().min(64).max(64).regex(new RegExp("^[0-9a-f]{64}$")),
  "project_pseudonym_sha256": z.string().min(64).max(64).regex(new RegExp("^[0-9a-f]{64}$")),
  "retrospective_only": z.literal(true).optional(),
  "influenced_live_decision": z.literal(false).optional(),
  "data_classification": z.literal("DEIDENTIFIED_AUTHORIZED"),
  "authorization_sha256": z.string().min(64).max(64).regex(new RegExp("^[0-9a-f]{64}$")),
  "consent_to_approved_aggregate_export": z.boolean(),
  "consent_record_sha256": z.string().min(64).max(64).regex(new RegExp("^[0-9a-f]{64}$")),
  "organizational_review_sha256": z.string().min(64).max(64).regex(new RegExp("^[0-9a-f]{64}$")),
  "independent_panel_record_sha256": z.string().min(64).max(64).regex(new RegExp("^[0-9a-f]{64}$")),
  "historical_review_record_sha256": z.string().min(64).max(64).regex(new RegExp("^[0-9a-f]{64}$")),
  "approved_aggregate_sha256": z.string().min(64).max(64).regex(new RegExp("^[0-9a-f]{64}$")),
  "person_hours": z.number().min(0),
  "review_cycles": z.number().int().min(0),
  "discrepancies": z.number().int().min(0),
  "surfaced_assumptions": z.number().int().min(0),
  "disposition_agreement": z.boolean(),
  "all_discrepancies_adjudicated": z.boolean(),
  "completed_at": z.string().refine((value) => !Number.isNaN(Date.parse(value)) && /(?:Z|[+-]\d{2}:\d{2})$/.test(value), "Expected timezone-aware ISO date-time"),
  "raw_partner_data_uploaded_to_synthetic_project": z.literal(false).optional(),
}).strict();
export type ShadowProjectRecord = z.infer<typeof ShadowProjectRecordSchema>;

export const ExperimentClaimLedgerSchema = z.object({
  "schema_version": z.literal("ecocorridor-usefulness-study/v1.0").optional(),
  "ledger_id": z.string().min(1).max(128),
  "protocol_sha256": z.string().min(64).max(64).regex(new RegExp("^[0-9a-f]{64}$")),
  "generated_at": z.string().refine((value) => !Number.isNaN(Date.parse(value)) && /(?:Z|[+-]\d{2}:\d{2})$/.test(value), "Expected timezone-aware ISO date-time"),
  "claims": z.array(z.object({
  "claim_id": z.string().min(1).max(128),
  "level": z.enum(["TRACE_INTEGRITY", "SYNTHETIC_TASK_CORRECTNESS", "PRACTITIONER_WORKFLOW_IMPROVEMENT", "EXTERNAL_WORKFLOW_UTILITY"]),
  "status": z.enum(["BLOCKED", "NOT_SUPPORTED", "SUPPORTED"]),
  "bounded_claim": z.string().min(1).max(1000),
  "reason": z.string().min(1).max(1600),
  "supporting_evidence_sha256s": z.array(z.string().min(64).max(64).regex(new RegExp("^[0-9a-f]{64}$"))).optional(),
  "limitations": z.array(z.string()).min(1),
}).strict()).min(4).max(6),
  "prohibited_inferences": z.array(z.string()).min(1),
  "ledger_sha256": z.union([z.string().min(64).max(64).regex(new RegExp("^[0-9a-f]{64}$")), z.null()]).optional(),
}).strict();
export type ExperimentClaimLedger = z.infer<typeof ExperimentClaimLedgerSchema>;

